using Microsoft.EntityFrameworkCore;

namespace AcSimulator.Api.Infrastructure;
public sealed class RetentionWorker(IServiceScopeFactory scopes,IWebHostEnvironment environment,IConfiguration configuration,ILogger<RetentionWorker> logger):BackgroundService {
  protected override async Task ExecuteAsync(CancellationToken stoppingToken){while(!stoppingToken.IsCancellationRequested){try{using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();var days=Math.Clamp(configuration.GetValue("RetentionDays",30),7,365);var cutoff=DateTime.UtcNow.AddDays(-days);var expired=await db.Projects.IgnoreQueryFilters().Where(x=>x.DeletedAt!=null&&x.DeletedAt<cutoff).Select(x=>x.Id).ToListAsync(stoppingToken);if(expired.Count>0){var reportIds=await db.Reports.IgnoreQueryFilters().Where(x=>expired.Contains(x.ProjectId)).Select(x=>x.Id).ToListAsync(stoppingToken);var projects=await db.Projects.IgnoreQueryFilters().Where(x=>expired.Contains(x.Id)).ToListAsync(stoppingToken);db.Projects.RemoveRange(projects);await db.SaveChangesAsync(stoppingToken);var reportDir=Path.Combine(environment.WebRootPath??Path.Combine(environment.ContentRootPath,"wwwroot"),"reports");foreach(var reportId in reportIds){var path=Path.Combine(reportDir,$"{reportId:N}.pdf");if(File.Exists(path))File.Delete(path);}logger.LogInformation("Purged {ProjectCount} projects beyond retention",projects.Count);}}catch(OperationCanceledException)when(stoppingToken.IsCancellationRequested){return;}catch(Exception ex){logger.LogError(ex,"Project retention cleanup failed");}await Task.Delay(TimeSpan.FromHours(24),stoppingToken);}}
}
